package cn.workbench;
import org.springframework.web.bind.annotation.*;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.security.crypto.password.PasswordEncoder;
@RestController @RequestMapping("/api/v1") public class OrganizationController {
 final Store db;final Records r;final Policy p;final Writes w;final PasswordEncoder passwords;public OrganizationController(Store db,Records r,Policy p,Writes w,PasswordEncoder passwords){this.db=db;this.r=r;this.p=p;this.w=w;this.passwords=passwords;}
 static final Map<String,String>KINDS=Map.of("companies","COMPANY","departments","DEPARTMENT","tags","TAG","rules","RULE","notification-channels","CHANNEL");
 @GetMapping("/organization/departments") Object departments(HttpServletRequest q,@RequestParam(required=false)Integer companyId){var a=p.actor(q);Integer company=companyId==null?a.company():companyId;if(company!=null&&!a.globalAdmin())p.company(a,company);return Api.ok(r.list("DEPARTMENT",company,null).stream().filter(d->Boolean.TRUE.equals(d.get("enabled"))).toList());}
 @GetMapping("/organization/collaboration-departments") Object collaborationDepartments(HttpServletRequest request){
  var actor=p.actor(request);if(!actor.leader()&&!actor.globalAdmin())throw ApiException.denied();
  Map<Integer,String> companies=new TreeMap<>();
  for(var company:r.list("COMPANY",null,null))if(Boolean.TRUE.equals(company.get("enabled")))companies.put(Jsons.integer(company.get("id")),String.valueOf(company.get("name")));
  return Api.ok(r.list("DEPARTMENT",null,null).stream()
   .filter(department->Boolean.TRUE.equals(department.get("enabled"))&&companies.containsKey(Jsons.integer(department.get("companyId"))))
   .sorted(Comparator.<Map<String,Object>>comparingInt(department->Jsons.integer(department.get("companyId"))).thenComparingLong(department->Jsons.number(department.get("id"))))
   .map(department->Records.map("id",department.get("id"),"name",department.get("name"),"companyId",department.get("companyId"),"companyName",companies.get(Jsons.integer(department.get("companyId")))))
   .toList());
 }
 @GetMapping("/organization/users") Object users(HttpServletRequest q,@RequestParam(required=false)Integer deptId){var a=p.actor(q);if(!a.leader())deptId=a.dept();Integer filter=deptId;List<Map<String,Object>> users=new ArrayList<>();for(var u:db.users()){long id=Jsons.number(u.get("id"));var scopes=db.scopes(id);if(scopes.stream().anyMatch(s->(a.company()==null||(a.company()==null||Objects.equals(a.company(),s.get("companyId")==null?null:Jsons.integer(s.get("companyId")))))&&(filter==null||Objects.equals(filter,s.get("deptId")==null?null:Jsons.integer(s.get("deptId"))))))users.add(Records.map("id",id,"name",u.get("name"),"enabled",u.get("enabled")));}return Api.ok(users);}
 @GetMapping("/admin/{resource:companies|departments|tags|rules|notification-channels|users}") Object adminList(@PathVariable String resource,HttpServletRequest q){var a=p.actor(q);p.admin(a);if(resource.equals("users"))return Api.ok(db.users().stream().filter(u->db.rawScopes(Jsons.number(u.get("id"))).stream().anyMatch(s->(a.company()==null||Objects.equals(a.company(),s.get("companyId")==null?null:Jsons.integer(s.get("companyId")))))).map(u->Records.map("id",u.get("id"),"name",u.get("name"),"accountSuffix",String.valueOf(u.get("account")).substring(Math.max(0,String.valueOf(u.get("account")).length()-4)),"enabled",u.get("enabled"),"scopes",db.rawScopes(Jsons.number(u.get("id"))).stream().filter(s->a.company()==null||Objects.equals(a.company(),s.get("companyId")==null?null:Jsons.integer(s.get("companyId")))).toList())).toList());var list=r.list(KINDS.get(resource),resource.equals("companies")?null:a.company(),null);if(resource.equals("companies")&&a.company()!=null)list=list.stream().filter(c->Objects.equals(a.company(),Jsons.integer(c.get("id")))).toList();return Api.ok(list);}
 @PostMapping("/admin/{resource:companies|departments|tags|rules|notification-channels|users}") Object create(@PathVariable String resource,@RequestBody Map<String,Object>b,HttpServletRequest q){var a=p.actor(q);p.admin(a);p.freshTotp(q);return w.run(q,b,()->{if(resource.equals("users")){String account=TaskService.text(b,"account",80),name=TaskService.text(b,"name",100),password=TaskService.text(b,b.containsKey("initialPassword")?"initialPassword":"password",72);if(password.length()<12)throw TaskService.invalid("初始密码至少12位");var scopes=scopes(a,b);var u=Records.map("account",account,"name",name,"passwordHash",passwords.encode(password),"mustChangePassword",true);db.insertUser(u);for(var scope:scopes){scope.put("userId",u.get("id"));db.insertScope(scope);}w.audit(a,"USER_CREATE",Jsons.number(u.get("id")));return Records.map("id",u.get("id"),"name",name);}if(resource.equals("companies")){if(a.company()!=null)throw ApiException.denied();String code=TaskService.text(b,"code",30);if(!code.matches("[A-Za-z0-9_]{1,30}"))throw TaskService.invalid("公司编码仅允许字母、数字、下划线");var company=r.create("COMPANY",0,null,null,a.uid(),"ACTIVE",Records.map("name",TaskService.text(b,"name",200),"companyCode",code,"enabled",true));w.audit(a,"COMPANY_CREATE",Jsons.number(company.get("id")));return company;}boolean global="GLOBAL".equals(b.get("scope"));if(global&&(a.company()!=null||!Set.of("tags","rules").contains(resource)))throw ApiException.denied();int company=global?0:b.get("companyId")==null?Objects.requireNonNull(a.company()):TaskService.integer(b,"companyId");if(!global)p.infrastructureCompany(a,company);var body=new LinkedHashMap<String,Object>();for(String field:List.of("code","name","enabled","weight","ruleVersion","keywords","negativeKeywords","negativeWords","fixedPhrases","envKey","deptId","role","priority","type"))if(b.containsKey(field))body.put(field,b.get(field));body.put("name",TaskService.text(b,"name",200));body.putIfAbsent("enabled",true);body.putIfAbsent("weight",100);body.putIfAbsent("ruleVersion",1);if(resource.equals("notification-channels"))body.put("enabled",false);Integer dept=b.get("deptId")==null?null:Jsons.integer(b.get("deptId"));if(dept!=null){var target=r.get(dept);if(!"DEPARTMENT".equals(target.get("kind"))||!Boolean.TRUE.equals(target.get("enabled"))||!global&&TaskService.integer(target,"companyId")!=company)throw ApiException.denied();}var created=r.create(KINDS.get(resource),company,dept,null,a.uid(),"ACTIVE",body);w.audit(a,"ADMIN_CREATE_"+resource,Jsons.number(created.get("id")));return created;});}
 @RequestMapping(value="/admin/{resource:companies|departments|tags|rules|notification-channels|users}/{id}",method={RequestMethod.PUT,RequestMethod.PATCH,RequestMethod.DELETE}) Object edit(@PathVariable String resource,@PathVariable long id,@RequestBody(required=false)Map<String,Object>body,HttpServletRequest q){var a=p.actor(q);p.admin(a);p.freshTotp(q);var b=body==null?new LinkedHashMap<String,Object>():body;return w.run(q,b,()->{if(resource.equals("users")){var existing=db.rawScopes(id);if(existing.isEmpty()||a.company()!=null&&existing.stream().anyMatch(s->!Objects.equals(a.company(),s.get("companyId")==null?null:Jsons.integer(s.get("companyId")))||"GROUP_LEADER".equals(s.get("role"))))throw ApiException.denied();var user=db.user(id);db.adminUser(id,b.containsKey("name")?TaskService.text(b,"name",100):String.valueOf(user.get("name")),!q.getMethod().equals("DELETE")&&(b.containsKey("enabled")?Boolean.TRUE.equals(b.get("enabled")):Boolean.TRUE.equals(user.get("enabled"))));if(b.get("password") instanceof String password&&!password.isBlank()){if(password.length()<12||password.length()>72)throw TaskService.invalid("密码长度须12至72位");db.resetPassword(id,passwords.encode(password));}if(b.containsKey("scopes")){var scopes=scopes(a,b);db.revokeScopes(id);for(var scope:scopes){scope.put("userId",id);db.insertScope(scope);}}w.audit(a,"USER_ENABLED",id);return Map.of();}var item=r.lock(id);if(!Objects.equals(KINDS.get(resource),item.get("kind")))throw ApiException.denied();if(resource.equals("companies")){if(a.company()!=null&&!Objects.equals(a.company(),(int)id))throw ApiException.denied();}else p.infrastructureCompany(a,TaskService.integer(item,"companyId"));if(q.getMethod().equals("DELETE")){item.put("enabled",false);item.put("status","DISABLED");}else {TaskService.version(item,b);for(String key:List.of("name","enabled","weight","keywords","negativeWords","fixedPhrases"))if(b.containsKey(key))item.put(key,b.get(key));if(b.containsKey("enabled"))item.put("status",Boolean.TRUE.equals(b.get("enabled"))?"ACTIVE":"DISABLED");if(resource.equals("rules"))item.put("ruleVersion",TaskService.integer(item,"ruleVersion")+1);}r.save(item);w.audit(a,"ADMIN_UPDATE_"+resource,id);return item;});}
 @PostMapping("/tasks/match") Object match(@RequestBody Map<String,Object>b,HttpServletRequest q){
  var actor=p.actor(q);int company=TaskService.integer(b,"companyId");p.taskLeader(actor,company);
  String title=TaskService.text(b,"title",300);Object contentValue=b.getOrDefault("content","");
  if(!(contentValue instanceof String content)||content.length()>20000)throw TaskService.invalid("Invalid matching content");
  return w.run(q,b,()->{
   List<Map<String,Object>> tags=new ArrayList<>(r.list("TAG",0,null));tags.addAll(r.list("TAG",company,null));
   List<Map<String,Object>> rules=new ArrayList<>(r.list("RULE",0,null));rules.addAll(r.list("RULE",company,null));
   Map<String,Object> evaluated=new MatchingEngine().match(company,title,content,r.list("DEPARTMENT",company,null),tags,rules);
   Map<String,Object> snapshot=new LinkedHashMap<>(evaluated);
   snapshot.put("inputSnapshot",Records.map("companyId",company,"title",title,"content",content));
   var saved=r.create("MATCHING_RESULT",company,null,null,actor.uid(),"SUGGESTED",snapshot);
   w.audit(actor,"MATCHING_SUGGEST",Jsons.number(saved.get("id")));
   Map<String,Object> response=new LinkedHashMap<>(evaluated);
   response.remove("ruleSnapshot");response.remove("normalizedTitle");response.remove("normalizedContent");
   response.put("matchingResultId",saved.get("id"));return response;
  });
 }


 List<Map<String,Object>> scopes(Policy.Actor a,Map<String,Object>b){List<?> inputs=b.get("scopes") instanceof List<?> list?list:List.of(b);if(inputs.isEmpty()||inputs.size()>12)throw TaskService.invalid("身份范围数量须1至12");List<Map<String,Object>> result=new ArrayList<>();Set<String> unique=new HashSet<>();for(Object input:inputs){if(!(input instanceof Map<?,?> raw))throw TaskService.invalid("身份范围无效");Map<String,Object> scope=new LinkedHashMap<>();for(var entry:raw.entrySet())scope.put(String.valueOf(entry.getKey()),entry.getValue());String role=TaskService.text(scope,"role",40);if(!Set.of("ADMIN","GROUP_LEADER","DIVISION_LEADER","COMPANY_LEADER","DEPT_HEAD","EMPLOYEE").contains(role))throw TaskService.invalid("角色无效");Integer company=scope.get("companyId")==null?null:TaskService.integer(scope,"companyId");Integer dept=scope.get("deptId")==null?null:TaskService.integer(scope,"deptId");if(role.equals("GROUP_LEADER")&&(company!=null||dept!=null||a.company()!=null))throw ApiException.denied();if(company==null){if(a.company()!=null||!Set.of("GROUP_LEADER","ADMIN").contains(role)||dept!=null)throw ApiException.denied();}else p.infrastructureCompany(a,company);if(Set.of("EMPLOYEE","DEPT_HEAD").contains(role)&&dept==null)throw TaskService.invalid("员工和部门主管必须绑定部门");if(dept!=null){var department=r.get(dept);if(!department.get("kind").equals("DEPARTMENT")||!Objects.equals(company,Jsons.integer(department.get("companyId"))))throw ApiException.denied();}String key=role+":"+company+":"+dept;if(!unique.add(key))throw TaskService.invalid("身份范围重复");result.add(Records.map("role",role,"companyId",company,"deptId",dept));}return result;}
}
